 "content": "def transform(grid):
    """Composite four 3-row layers; earlier (higher) color layers cover later ones."""
    h = len(grid) // 4
    if h * 4 != len(grid):
        raise ValueError("expected four equal-height layers")
    layers = [grid[i * h:(i + 1) * h] for i in range(4)]
    out = [[0 for _ in row] for row in layers[0]]
    for layer in reversed(layers):
        for r, row in enumerate(layer):
            for c, value in enumerate(row):
                if value:
                    out[r][c] = value
    return out
