    layers = [grid[i * h:(i + 1) * h] for i in range(4)]
    # Layer colors by position: 5, 4, 2, 8. Overlay bottom-to-top so
    # the observed priority is 5 > 4 > 8 > 2.
    order = [2, 3, 1, 0]
    out = [[0 for _ in row] for row in layers[0]]
    for index in order:
        for r, row in enumerate(layers[index]):
            for c, value in enumerate(row):
                if value:
                    out[r][c] = value
    return out
